precision highp float;
varying vec2 vUv;
uniform sampler2D inputTexture;
uniform vec2 resolution;
uniform vec2 originalResolution;
uniform vec2 inputTextureResolution;
uniform float threshold;
// Original samplers: straight RGBA; intermediate samplers: premultiplied RGBA.
// Only the final pass writes straight RGBA. All UVs use image coordinates (Y down).
vec4 mfToStraight(vec4 color) {
  return vec4(color.a > 0.0 ? color.rgb / color.a : vec3(0.0), color.a);
}
vec4 mfOriginalBilinear(sampler2D image, vec2 uv, vec2 size) {
  vec2 pixel = uv * size - 0.5, base = floor(pixel), fraction = fract(pixel);
  vec2 texel = 1.0 / size, origin = (base + 0.5) * texel;
  vec4 a = texture2D(image, origin);
  vec4 b = texture2D(image, origin + vec2(texel.x, 0.0));
  vec4 c = texture2D(image, origin + vec2(0.0, texel.y));
  vec4 d = texture2D(image, origin + texel);
  a.rgb *= a.a; b.rgb *= b.a; c.rgb *= c.a; d.rgb *= d.a;
  return mix(mix(a, b, fraction.x), mix(c, d, fraction.x), fraction.y);
}
// Exact box overlap for supported downsample footprints (at most 4 source pixels).
vec4 mfDownsampleOriginal(sampler2D image, vec2 uv, vec2 size, vec2 targetSize) {
  vec2 footprint = size / targetSize;
  vec2 low = uv * size - footprint * 0.5, high = low + footprint, base = floor(low);
  vec4 sum = vec4(0.0);
  float total = 0.0;
  for (int y = 0; y < 5; y++) {
    for (int x = 0; x < 5; x++) {
      vec2 pixel = base + vec2(float(x), float(y));
      vec2 overlap = max(vec2(0.0), min(pixel + 1.0, high) - max(pixel, low));
      float weight = overlap.x * overlap.y;
      vec4 color = texture2D(image, (pixel + 0.5) / size);
      sum += vec4(color.rgb * color.a, color.a) * weight;
      total += weight;
    }
  }
  return sum / max(total, 0.000001);
}
void main() {
  vec4 color = mfDownsampleOriginal(inputTexture, vUv, inputTextureResolution, resolution);
  vec3 straightColor = mfToStraight(color).rgb;
  float brightness = max(straightColor.r, max(straightColor.g, straightColor.b));
  float cutoff = clamp(threshold, 0.0, 1.0);
  float weight = max(brightness - cutoff, 0.0) / max(1.0 - cutoff, 0.000001);
  gl_FragColor = color * weight;
}

precision highp float;
varying vec2 vUv;
uniform sampler2D inputTexture;
uniform vec2 resolution;
uniform vec2 originalResolution;
uniform vec2 inputTextureResolution;
uniform float ghostCount;
uniform float spacing;
uniform float haloRadius;
uniform float chromaticAberration;
vec4 mfFlareTexel(vec2 pixel) {
  if (pixel.x < 0.0 || pixel.y < 0.0 || pixel.x >= inputTextureResolution.x || pixel.y >= inputTextureResolution.y) return vec4(0.0);
  return texture2D(inputTexture, (pixel + 0.5) / inputTextureResolution);
}
vec4 mfFlareSample(vec2 uv) {
  vec2 pixel = uv * inputTextureResolution - 0.5;
  vec2 base = floor(pixel), fraction = fract(pixel);
  return mix(mix(mfFlareTexel(base), mfFlareTexel(base + vec2(1.0, 0.0)), fraction.x),
    mix(mfFlareTexel(base + vec2(0.0, 1.0)), mfFlareTexel(base + vec2(1.0)), fraction.x), fraction.y);
}

vec4 mfChromatic(vec2 uv, vec2 direction) {
  vec2 shift = direction * clamp(chromaticAberration, 0.0, 16.0) / originalResolution;
  vec4 red = mfFlareSample(uv + shift), green = mfFlareSample(uv), blue = mfFlareSample(uv - shift);
  return vec4(red.r, green.g, blue.b, max(red.a, max(green.a, blue.a)));
}
void main() {
  vec2 aspect = vec2(originalResolution.x / originalResolution.y, 1.0);
  vec2 mirrored = vec2(1.0) - vUv;
  vec2 centerVector = (vec2(0.5) - mirrored) * aspect;
  vec2 direction = centerVector / max(length(centerVector), 0.000001);
  vec2 ghostVector = (vec2(0.5) - mirrored) * clamp(spacing, 0.0, 1.0);
  float count = floor(clamp(ghostCount, 0.0, 8.0) + 0.5);
  vec4 sum = vec4(0.0);
  for (int i = 0; i < 8; i++) {
    if (float(i) < count) {
      vec2 uv = mirrored + ghostVector * float(i + 1);
      float weight = pow(1.0 - clamp(length((uv - 0.5) * aspect), 0.0, 1.0), 2.0);
      sum += mfChromatic(uv, direction) * weight;
    }
  }
  float radius = clamp(haloRadius, 0.0, 1.0);
  if (radius > 0.0) {
    vec2 uv = mirrored + direction * radius / aspect;
    float weight = pow(1.0 - clamp(length((uv - 0.5) * aspect), 0.0, 1.0), 2.0);
    sum += mfChromatic(uv, direction) * weight;
  }
  gl_FragColor = sum / max(count + (radius > 0.0 ? 1.0 : 0.0), 1.0);
}

precision highp float;
varying vec2 vUv;
uniform sampler2D inputTexture;
uniform vec2 resolution;
uniform vec2 originalResolution;
uniform vec2 inputTextureResolution;
uniform float blurRadius;
vec4 mfFlareTexel(vec2 pixel) {
  if (pixel.x < 0.0 || pixel.y < 0.0 || pixel.x >= inputTextureResolution.x || pixel.y >= inputTextureResolution.y) return vec4(0.0);
  return texture2D(inputTexture, (pixel + 0.5) / inputTextureResolution);
}
vec4 mfFlareSample(vec2 uv) {
  vec2 pixel = uv * inputTextureResolution - 0.5;
  vec2 base = floor(pixel), fraction = fract(pixel);
  return mix(mix(mfFlareTexel(base), mfFlareTexel(base + vec2(1.0, 0.0)), fraction.x),
    mix(mfFlareTexel(base + vec2(0.0, 1.0)), mfFlareTexel(base + vec2(1.0)), fraction.x), fraction.y);
}

void main() {
  float radius = clamp(blurRadius, 0.0, 64.0);
  if (radius <= 0.0) { gl_FragColor = mfFlareSample(vUv); return; }
  vec2 spacing = vec2(radius / originalResolution.x / 8.0, 0.0);
  vec4 sum = vec4(0.0);
  float total = 0.0;
  for (int i = -8; i <= 8; i++) {
    float weight = exp(-float(i * i) / 18.0);
    sum += mfFlareSample(vUv + spacing * float(i)) * weight;
    total += weight;
  }
  gl_FragColor = sum / total;
}

