  arr=([]);
  for (let i = 0; i < num; i += 1){
    v=vec2(0,60*floor(i/4));
    arr.push(v);
  }
  to=(index) => {
    for (let i = 0; i < num; i += 1){
      v=(arr[i]);
      tween(v).to(vec2(getBitmapFontCode(floor(rnd(0x20,0x7f))),v.y),500+i*10).easing(ease.Quadratic.Out).start();
