clip.use("centi");
let cue_name = "";
let last_cue_time = 0;
let beat0;
setup(() => {
  size(1920, 1080);
});

onFrame(({ time, frame, progress, compTime, compFrame, runTime, runFrame, bar, beat }) => {
  clear();
  col(255);
  font(28);
  text(cue_name, 120, 31);
  for(let i=0; i<4; i++){
    if (beat0 == i) col(255);
    else col(100);
    rect(20 + 20 * i, 20, 10, 10);
  }
});

onEnter(({ time, frame, progress, compTime, compFrame, runTime, runFrame, bar, beat }) => {
});

onBeat(({ time, frame, progress, compTime, compFrame, runTime, runFrame, bar, beat }) => {
  beat0 = beat - 1;
});

onCue(({runTime, cueName}) =>{
  if ( runTime - last_cue_time < 0.2) return;
  cue_name = cueName;
  const next_cue = "Cue" + floor(random()*6);
  cue_name = cue_name + " - " + next_cue;
  go(next_cue);

  last_cue_time = runTime;
});

