  clear();
  t += 1 / 30;

  const sides = 70;
  const angleStep = (2 * PI) / sides;
  const depthStep = 0.25;
  let angle = 0;
  let z = Z + 8;

  while (z > Z) {
    for (let i = 0; i < sides; i += 1) {
      let fog = 1 / max(z + 0.7 - 3, 1);

      if (z <= 2) {
        fog = max(0, (z / 2) * (z / 2));
      }

      let brightness = floor(
        205 * fog * abs(sin((i / sides) * 2 * PI + t))
      );
      brightness *= 0.55 + 0.45 * cos((i / sides + 0.25) * PI * 5);
      brightness = floor(brightness);

      col(brightness);
      quad(angle, angleStep, z, depthStep);

      if (i % 3 === 0) {
        col(0);
        quad(angle, angleStep / 10, z, depthStep);
      }

      angle += angleStep;
    }

    z -= depthStep;
  }

  Z -= 0.05;
  if (Z <= depthStep) Z += depthStep;
});

