let Z = -0.2;
let t = 0;

const project = (angle, z) => {
  const radius = width / 10;
  const tunnelRadius = width / 3;
  const wobble = -10 * cos(angle * 4 + t);

  return vec2(
    width / 2 +
      (tunnelRadius * cos(angle) + radius * sin(z + 2 * t)) / z +
      cos(angle) * wobble,
    height / 2 +
      (tunnelRadius * sin(angle)) / z +
      sin(angle) * wobble
  );
};

const quad = (angle, angleStep, z, depthStep) => {
  const vertices = [
    project(angle, z),
    project(angle + angleStep, z),
    project(angle + angleStep, z + depthStep),
    project(angle, z + depthStep)
  ];

  fill();
  beginShape();
  moveTo(vertices[0].x, vertices[0].y);

  for (let i = 0; i < 4; i += 1) {
    lineTo(vertices[i].x, vertices[i].y);
  }

  endShape();
};

