precision highp float;
varying vec2 vUv;
uniform sampler2D inputTexture;
uniform vec2 resolution;
uniform vec3 shadowColor;
uniform vec3 highlightColor;
uniform float strength;

void main() {
  vec4 original = texture2D(inputTexture, vUv);
  if (strength <= 0.0) { gl_FragColor = original; return; }
  vec4 result = original;
  result.rgb = mix(shadowColor, highlightColor, dot(original.rgb, vec3(0.2126, 0.7152, 0.0722)));
  vec4 mixed = mix(vec4(original.rgb * original.a, original.a), vec4(result.rgb * result.a, result.a), clamp(strength, 0.0, 1.0));
  gl_FragColor = vec4(mixed.a > 0.0 ? mixed.rgb / mixed.a : vec3(0.0), mixed.a);
}

precision highp float;
varying vec2 vUv;
uniform sampler2D inputTexture;
uniform vec2 resolution;
uniform float axis;
uniform float segments;
uniform float angle;
uniform vec2 center;
uniform float strength;
vec4 mfSamplePremultiplied(vec2 uv) {
  vec2 pixel = uv * resolution - 0.5;
  vec2 base = floor(pixel), fraction = fract(pixel);
  vec2 texel = 1.0 / resolution, origin = (base + 0.5) * texel;
  vec4 a = texture2D(inputTexture, origin);
  vec4 b = texture2D(inputTexture, origin + vec2(texel.x, 0.0));
  vec4 c = texture2D(inputTexture, origin + vec2(0.0, texel.y));
  vec4 d = texture2D(inputTexture, origin + texel);
  a.rgb *= a.a; b.rgb *= b.a; c.rgb *= c.a; d.rgb *= d.a;
  return mix(mix(a, b, fraction.x), mix(c, d, fraction.x), fraction.y);
}
vec4 mfStraight(vec4 color) {
  return vec4(color.a > 0.0 ? color.rgb / color.a : vec3(0.0), color.a);
}
void main() {
  vec4 original = texture2D(inputTexture, vUv);
  if (strength <= 0.0) { gl_FragColor = original; return; }
  vec4 result = original;
  vec2 pixel = (vUv - center) * resolution;
  float radians = angle * 0.0174532925199433;
  vec2 aligned = vec2(cos(radians) * pixel.x + sin(radians) * pixel.y,
    -sin(radians) * pixel.x + cos(radians) * pixel.y);
  float count = clamp(floor(segments + 0.5), 1.0, 12.0);
  if (count <= 1.0) {
    if (axis < 0.5) aligned.x = abs(aligned.x);
    else aligned.y = abs(aligned.y);
  } else {
    float sector = 6.283185307179586 / count;
    float folded = abs(mod(atan(aligned.y, aligned.x) + sector * 0.5, sector) - sector * 0.5);
    aligned = length(aligned) * vec2(cos(folded), sin(folded));
  }
  vec2 sourcePixel = vec2(cos(radians) * aligned.x - sin(radians) * aligned.y,
    sin(radians) * aligned.x + cos(radians) * aligned.y);
  result = mfStraight(mfSamplePremultiplied(center + sourcePixel / resolution));
  vec4 mixed = mix(vec4(original.rgb * original.a, original.a), vec4(result.rgb * result.a, result.a), clamp(strength, 0.0, 1.0));
  gl_FragColor = vec4(mixed.a > 0.0 ? mixed.rgb / mixed.a : vec3(0.0), mixed.a);
}

precision highp float;
varying vec2 vUv;
uniform sampler2D inputTexture;
uniform vec2 resolution;
uniform vec2 offset;
uniform float strength;

void main() {
  vec4 original = texture2D(inputTexture, vUv);
  if (strength <= 0.0) { gl_FragColor = original; return; }
  vec4 result = original;
  vec2 shift = offset / resolution;
  vec4 red = texture2D(inputTexture, vUv + shift);
  vec4 blue = texture2D(inputTexture, vUv - shift);
  float alpha = max(original.a, max(red.a, blue.a));
  vec3 rgb = vec3(red.r * red.a, original.g * original.a, blue.b * blue.a);
  result = vec4(alpha > 0.0 ? rgb / alpha : vec3(0.0), alpha);
  vec4 mixed = mix(vec4(original.rgb * original.a, original.a), vec4(result.rgb * result.a, result.a), clamp(strength, 0.0, 1.0));
  gl_FragColor = vec4(mixed.a > 0.0 ? mixed.rgb / mixed.a : vec3(0.0), mixed.a);
}

